// Throwaway design study: three experiment-detail layouts on one route (?variant=A|B|C).
// All data, edits, history and execution are simulated in memory. No backend calls.
const $ = s => document.querySelector(s);
const icons = {folder:'M3 6h6l2 2h10v12H3z',arrow:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',plus:'M12 5v14M5 12h14',play:'m8 5 12 7-12 7z',file:'M5 3h9l5 5v13H5zM14 3v6h5',crop:'M6 3v15h15M3 6h15v15',cells:'M9 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M22 9a4 4 0 1 1-8 0 4 4 0 0 1 8 0M15 19a4 4 0 1 1-8 0 4 4 0 0 1 8 0',chevron:'m5 9 7 7 7-7',dot:'M12 8v5M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn = (text, action, primary=false, ico='') => `<button type="button" data-action="${action}" class="${primary?'primary':''}">${ico?icon(ico):''}${text}</button>`;
const projects = [
 {id:1,name:'Calcium activity · baseline study',description:'Miniscope recordings · 2026',open:true},
 {id:2,name:'Multimodal sleep recordings',description:'Calcium imaging + electrophysiology',open:false},
 {id:3,name:'Pilot recordings',description:'Electrophysiology · method development',open:false}
];
const initial = [
 [96,1,'Baseline · session 04','Rat 01','Sep 21, 2026','Review neurons','Miniscope'],
 [97,1,'Baseline · session 05','Rat 01','Sep 22, 2026','Ready to run','Miniscope'],
 [98,1,'Baseline · session 03','Rat 02','Sep 20, 2026','Complete','Miniscope'],
 [102,2,'Sleep · session 02','Rat 04','Sep 19, 2026','Check data','Multimodal'],
 [103,2,'Sleep · session 03','Rat 04','Sep 20, 2026','Complete','Multimodal'],
 [110,3,'Pilot · session 01','Rat 06','Sep 18, 2026','Ready to run','Electrophysiology']
];
const experiments = initial.map(([id,project,name,subject,date,status,type])=>({id,project,name,subject,date,status,type,notes:'Baseline recording before intervention.',crop:[40,30,590,445],excluded:[3,8],selected:4,settings:{event:5,low:.1,high:1.5,motion:'Non-rigid'},history:[],dirty:false,run:0,progress:0}));
for(const e of experiments){e.history=[{name:'Initial analysis',when:'Sep 21 · 2:42 PM',snapshot:snapshot(e)},{name:'Recording added',when:'Sep 21 · 10:15 AM',snapshot:{...snapshot(e),crop:[0,0,640,480],excluded:[]}}];}
function snapshot(e){return structuredClone({name:e.name,subject:e.subject,notes:e.notes,crop:e.crop,excluded:e.excluded,settings:e.settings});}
const state={view:'home',experiment:96,tab:'overview',variant:new URLSearchParams(location.search).get('variant')||'A',search:'',attention:false,dialog:null,compare:null};
if(!['A','B','C'].includes(state.variant))state.variant='A';
const current=()=>experiments.find(e=>e.id===state.experiment);
const needs=e=>['Review neurons','Check data'].includes(e.status);
const badge=status=>`<span class="badge ${status==='Complete'?'green':status==='Running'?'blue':needs({status})?'amber':''}">${esc(status)}</span>`;
const names={A:'Tabbed experiment',B:'Experiment overview',C:'Guided steps'};
function render(){
 $('#app').innerHTML=`<header class="topbar"><div class="brand"><span class="brandmark">a</span>ACE<small>Experiments</small></div><div class="topright"><span class="demo">Design preview · sample data</span><span class="avatar">RP</span></div></header><main class="main">${state.view==='home'?home():detail()}<details class="prototype-state"><summary>Prototype state · changes last until reload</summary><pre>${esc(JSON.stringify({layout:state.variant,screen:state.view,experiment:state.experiment,section:state.tab,...(state.view==='detail'?snapshot(current()):{}),status:current().status},null,2))}</pre></details></main>${switcher()}`;
 bind();
}
function home(){
 const filtered=experiments.filter(e=>(!state.attention||needs(e))&&`${e.name} ${e.subject} ${e.id} ${projects.find(p=>p.id===e.project).name}`.toLowerCase().includes(state.search.toLowerCase()));
 return `<div class="heading"><div><div class="eyebrow">Your research workspace</div><h1>Projects</h1><p>Find a recording. Pick up where you left off.</p></div>${btn('Add project','add-project',true,'plus')}</div>
 ${state.dialog==='add-project'?`<form id="project-form" class="dialog"><h3>Add a project</h3><p>Give the project a name. In the finished app, you’ll choose an existing project folder or create a new one.</p><label class="field" style="margin-top:15px">Project name<input name="name" required placeholder="e.g. Calcium activity study"></label><div class="row"><button class="primary">Add demo project</button>${btn('Cancel','close-dialog')}</div></form>`:''}
 <div class="attention"><span class="symbol">${icon('dot')}</span><div><h3 style="margin:0">${experiments.filter(needs).length} experiments need your attention</h3><p>Review detected neurons or check a recording before continuing.</p></div>${btn(state.attention?'Show all experiments':'Show experiments','attention',false,'arrow')}</div>
 <div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="Search projects or experiments" placeholder="Search projects or experiments…" value="${esc(state.search)}"></label><span class="muted">${projects.length} projects &nbsp; / &nbsp; ${experiments.length} experiments</span></div>
 ${projects.filter(p=>!state.search&&!state.attention||filtered.some(e=>e.project===p.id)).map(p=>{const ex=filtered.filter(e=>e.project===p.id),open=p.open||state.search||state.attention;return `<section class="folder"><button class="folderhead" data-action="folder:${p.id}" aria-expanded="${!!open}"><span class="foldericon">${icon('folder')}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.description)}</small></span><span class="end">${ex.some(needs)?badge(`${ex.filter(needs).length} need attention`):''}<span class="muted">${ex.length} experiments</span>${icon(open?'chevron':'arrow')}</span></button>${open?`<div class="tablewrap"><table class="experiment-table"><thead><tr><th>EXPERIMENT</th><th>SUBJECT</th><th>RECORDED</th><th>STATUS</th><th></th></tr></thead><tbody>${ex.map(e=>`<tr><td><button data-action="open:${e.id}">${esc(e.name)}</button><small>Experiment ${e.id} · ${e.type}</small></td><td>${e.subject}</td><td class="oneline">${e.date}</td><td>${badge(e.status)}</td><td><button aria-label="Open ${esc(e.name)}" data-action="open:${e.id}">${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="5">No experiments yet. Add a recording to get started.</td></tr>'}</tbody></table></div><div style="padding:12px 20px;border-top:1px solid #edf0ee">${state.dialog===`add-experiment:${p.id}`?addExperimentForm(p):btn('Add experiment',`add-experiment:${p.id}`,false,'plus')}</div>`:''}</section>`}).join('')||'<div class="empty">No matching experiments.</div>'}
 <div class="below"><span>Your projects stay organized by their recording folders.</span><span>Sample workspace · nothing is written to disk</span></div>`;
}
const sections=[['overview','Overview'],['data','Data & settings'],['crop','Crop'],['neurons','Neurons'],['results','Results'],['history','History']];
function detail(){const e=current(),p=projects.find(p=>p.id===e.project);const available=sections.filter(([k])=>e.type!=='Electrophysiology'||!['crop','neurons'].includes(k));return `<nav class="breadcrumb" aria-label="Breadcrumb">${btn('Projects','home')}<span>/</span>${btn(esc(p.name),'home')}<span>/</span><span>Experiment ${e.id}</span></nav><div class="heading detail-title"><div><div class="eyebrow">${esc(e.type)} experiment</div><h1>${esc(e.name)}</h1><p>${esc(e.subject)} <span>·</span> ${e.date} <span>·</span> ${badge(e.status)} ${e.dirty?'<span class="badge amber">Unsaved changes</span>':''}</p></div><div class="row">${btn('Save a version','save-version',false,'clock')}${btn(e.awaitingReview?'Continue review':e.run?'View run':e.status==='Complete'?'Run again':'Run experiment','run',true,'play')}</div></div>${dialog(e)}
 ${state.variant==='C'?`<div class="guide"><aside class="guide-nav"><div class="eyebrow">Experiment steps</div>${available.map(([k,l],i)=>`<button class="${state.tab===k?'active':''}" data-action="tab:${k}">${i+1}. ${l}</button>`).join('')}</aside><div>${content(e)}</div></div>`:`<nav class="tabs" aria-label="Experiment sections">${available.map(([k,l])=>`<button class="${state.tab===k?'active':''}" data-action="tab:${k}" aria-current="${state.tab===k?'page':'false'}">${l}</button>`).join('')}</nav>${state.variant==='B'&&state.tab==='overview'?overviewB(e):content(e)}`}`;}
function content(e){return ({overview:overview,data:data,crop:crop,neurons:neurons,results:results,history:history})[state.tab](e);}
function overview(e){return `<div class="grid"><div><section class="panel"><div class="panel-head"><h2>Continue this experiment</h2>${badge(e.status)}</div>${e.type!=='Electrophysiology'?`<div class="task"><span class="number">1</span><div><strong>Check the field of view</strong><p>Keep the useful part of your recording.</p></div>${btn('Adjust crop','tab:crop')}</div><div class="task"><span class="number">2</span><div><strong>Review detected neurons</strong><p>Inspect each candidate and choose which to keep.</p></div>${btn('Review neurons','tab:neurons',true)}</div>`:''}<div class="task"><span class="number">${e.type==='Electrophysiology'?'1':'3'}</span><div><strong>Review settings and run</strong><p>Confirm your changes before analysis begins.</p></div>${btn('View settings','tab:data')}</div></section><section class="panel"><div class="panel-head"><h2>Recording at a glance</h2>${btn('View data','tab:data')}</div><dl class="facts"><div><dt>Subject</dt><dd>${esc(e.subject)}</dd></div><div><dt>Analysis</dt><dd>${e.type}</dd></div><div><dt>Recording date</dt><dd>${e.date}</dd></div><div><dt>Current version</dt><dd>${esc(e.history[0].name)}</dd></div></dl><div class="note">${esc(e.notes)}</div></section></div><aside><section class="panel"><div class="eyebrow">${e.type==='Electrophysiology'?'Signal preview':'Field of view'}</div>${e.type==='Electrophysiology'?trace(2):stage(e,'preview')}<p style="margin-top:12px">Illustrative sample · ${e.type==='Electrophysiology'?'electrical activity':'maximum projection'}</p></section><section class="panel"><h3>A history you can return to</h3><p>Save the settings and decisions behind your analysis. Compare versions or return to an earlier one.</p><div style="margin-top:16px">${btn('View history','tab:history',false,'clock')}</div></section></aside></div>`;}
function overviewB(e){return `<section class="panel"><div class="row space"><div><div class="eyebrow">Next action</div><h2>${e.type==='Electrophysiology'?'Check your recording settings':'Review this recording’s neurons'}</h2><p>Work through your experiment from this single overview.</p></div>${btn('Continue',e.type==='Electrophysiology'?'tab:data':'tab:neurons',true,'arrow')}</div></section><div class="overview-sections"><section class="panel"><h2>Recording & settings</h2><p>${e.subject} · ${e.type} · ${e.date}</p><dl class="facts"><div><dt>Event threshold</dt><dd>${e.settings.event}</dd></div><div><dt>Filter range</dt><dd>${e.settings.low}–${e.settings.high} Hz</dd></div></dl>${btn('Edit settings','tab:data')}</section><section class="panel"><h2>History</h2><p>Current version</p><h3 style="margin-top:18px">${esc(e.history[0].name)}</h3>${btn('Compare versions','tab:history')}</section>${e.type!=='Electrophysiology'?`<section class="panel"><h2>Crop the recording</h2><p>Choose the field of view used for analysis.</p><div style="margin-top:15px">${stage(e,'preview')}</div>${btn('Adjust crop','tab:crop')}</section><section class="panel"><h2>Neuron selection</h2><div class="review-stat">${12-e.excluded.length} <small style="font-size:13px">of 12 kept</small></div><p>Review outlines and activity traces before continuing.</p>${btn('Review neurons','tab:neurons')}</section>`:''}</div>`;}
function data(e){return `<form id="settings-form"><div class="grid"><div><section class="panel"><div class="panel-head"><h2>Experiment details</h2><span class="muted">Changes apply to this experiment</span></div><div class="form-grid"><label class="field">Experiment title<input name="name" required value="${esc(e.name)}"></label><label class="field">Subject<input name="subject" required value="${esc(e.subject)}"></label><label class="field wide">Notes<textarea name="notes" rows="2">${esc(e.notes)}</textarea></label></div></section><section class="panel"><h2>Analysis settings</h2><p>Start with the existing analysis settings. Adjust only what your experiment needs.</p><div class="form-grid" style="margin-top:23px">${e.type!=='Electrophysiology'?`<label class="field">Motion correction<select name="motion"><option ${e.settings.motion==='Non-rigid'?'selected':''}>Non-rigid</option><option ${e.settings.motion==='Rigid'?'selected':''}>Rigid</option></select><small>Correct movement between video frames.</small></label><label class="field">Event detection threshold<input name="event" type="number" step=".1" min="0" required value="${e.settings.event}"><small>Minimum event height used by the current analysis.</small></label>`:''}<label class="field">Lower filter frequency (Hz)<input name="low" type="number" min="0.001" step="any" required value="${e.settings.low}"></label><label class="field">Upper filter frequency (Hz)<input name="high" type="number" min="0.001" step="any" required value="${e.settings.high}"></label></div><details style="margin-top:24px;font-size:12px"><summary>Advanced parameters</summary><p>This design will expose all supported parameters here, grouped by analysis stage, with units and explanations. This preview includes a representative subset.</p></details><div class="footer-action"><button class="primary" type="submit">Apply changes</button></div></section></div><aside><section class="panel"><h3>Recording data</h3>${e.type!=='Electrophysiology'?file('Miniscope video','Rat01/session04/Miniscope/0.avi','Available'):''}${file('Timestamps','timeStamps.csv','Available')}${e.type!=='Miniscope'?file('Electrical recording','PFCLFPvsCBEEG.ncs',e.status==='Check data'?'Missing':'Available'):''}<div class="note">Files shown here are sample references. The finished app will help you locate missing recordings.</div></section></aside></div></form>`;}
function file(name,path,status){return `<div class="file">${icon('file')}<div><strong>${name}</strong><p>${path}</p></div><span class="badge ${status==='Missing'?'amber':'green'}">${status}</span></div>`;}
const positions=[[95,110],[172,87],[260,133],[361,88],[480,124],[549,204],[413,230],[299,231],[155,218],[104,342],[248,361],[419,365]];
function stage(e,mode){return `<div class="image-stage"><svg ${mode==='crop'?'id="crop-svg"':''} viewBox="0 0 640 480" role="img" aria-label="Synthetic microscopy projection${mode==='crop'?'. Drag to draw crop bounds. Numeric controls are also available.':''}"><defs><radialGradient id="bg"><stop stop-color="#344a40"/><stop offset="1" stop-color="#101b18"/></radialGradient><radialGradient id="glow"><stop stop-color="#b7c9ad" stop-opacity=".75"/><stop offset=".45" stop-color="#849c7b" stop-opacity=".42"/><stop offset="1" stop-color="#829679" stop-opacity="0"/></radialGradient><filter id="noise"><feTurbulence type="fractalNoise" baseFrequency=".33" numOctaves="3" seed="8"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".12"/></feComponentTransfer></filter></defs><rect width="640" height="480" fill="url(#bg)"/>${Array.from({length:65},(_,i)=>`<ellipse cx="${(i*179+44)%640}" cy="${(i*101+12)%480}" rx="${14+i%23}" ry="${11+i%19}" fill="url(#glow)" opacity=".5"/>`).join('')}${positions.map(([x,y],i)=>`<ellipse cx="${x}" cy="${y}" rx="${28+i%8}" ry="${24+i%9}" fill="url(#glow)"/>`).join('')}<rect width="640" height="480" filter="url(#noise)" opacity=".65"/>${mode==='neurons'?positions.map(([x,y],i)=>`<ellipse class="cell ${e.excluded.includes(i+1)?'excluded':''} ${e.selected===i+1?'selected':''}" data-action="cell:${i+1}" cx="${x}" cy="${y}" rx="${18+i%8}" ry="${13+i%9}" transform="rotate(${i*19} ${x} ${y})"/><text x="${x+25}" y="${y-17}" class="cell-label">${i+1}</text>`).join(''):''}${mode==='crop'?`<path id="crop-mask" d="${mask(e.crop)}" fill="#0008" fill-rule="evenodd"/><rect id="crop-rect" class="cropbox" x="${e.crop[0]}" y="${e.crop[1]}" width="${e.crop[2]-e.crop[0]}" height="${e.crop[3]-e.crop[1]}"/>`:''}<path d="M528 449h76" stroke="#d5e2d4" stroke-width="3"/><text x="530" y="438" fill="#d5e2d4" font-size="10">Sample image</text></svg>${mode!=='preview'?`<div class="stage-caption"><span>Synthetic preview · 640 × 480 px</span><span>${mode==='crop'?'Drag to select an area':'Select a numbered neuron'}</span></div>`:''}</div>`;}
const mask=c=>`M0 0H640V480H0Z M${c[0]} ${c[1]}H${c[2]}V${c[3]}H${c[0]}Z`;
function crop(e){return `<section class="panel"><div class="panel-head"><div><h2>Crop the recording</h2><p>Draw a rectangle around the area to analyze. Your raw video stays intact.</p></div><span class="badge green">In this workspace</span></div><div class="editor">${stage(e,'crop')}<div><h3>Field of view</h3><p>Keep the useful image area and exclude the edges.</p><form id="crop-form"><div class="form-grid" style="margin-top:22px">${['Left','Top','Right','Bottom'].map((label,i)=>`<label class="field">${label} (px)<input data-crop="${i}" name="c${i}" aria-label="${label} crop boundary" type="number" min="0" max="${i%2?480:640}" value="${e.crop[i]}" required></label>`).join('')}</div><div class="note">Changing the crop requires a new processing run. Previous neuron decisions may no longer apply to new detections.</div><div class="footer-action">${btn('Reset','reset-crop')}<button type="submit" class="primary">Apply crop</button></div></form></div></div></section>`;}
function trace(id){const points=Array.from({length:160},(_,i)=>`${i*3},${43-Math.sin(i*.38+id)*3-((i+id*7)%37<7?32*Math.exp(-((i+id*7)%37)/2):0)}`).join(' ');return `<div class="trace"><div class="muted">${id?'Activity trace · sample':'Sample signal'}</div><svg viewBox="0 0 480 60" role="img" aria-label="Illustrative activity trace"><path d="M0 49H480" stroke="#d9e5db"/><polyline points="${points}" stroke="#468b6d" stroke-width="1.7" fill="none"/></svg><div class="row space muted"><span>0 s</span><span>60 s</span></div></div>`;}
function neurons(e){return `<section class="panel"><div class="panel-head"><div><h2>Review detected neurons</h2><p>Select a neuron to inspect its outline and activity. Keep or exclude it from analysis.</p></div><span class="badge green">${12-e.excluded.length} kept · ${e.excluded.length} excluded</span></div><div class="editor"><div>${stage(e,'neurons')}${trace(e.selected)}</div><div><div class="eyebrow">Selected candidate</div><h2>Neuron ${String(e.selected).padStart(2,'0')}</h2><p>${e.excluded.includes(e.selected)?'Excluded from analysis':'Kept for analysis'}</p><div class="neuron-list">${positions.map((_,i)=>`<button aria-label="Select neuron ${i+1}" data-action="cell:${i+1}" class="${e.selected===i+1?'active':''} ${e.excluded.includes(i+1)?'excluded':''}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div>${btn(e.excluded.includes(e.selected)?'Keep this neuron':'Exclude this neuron','toggle-neuron',false,e.excluded.includes(e.selected)?'check':'cells')}<div class="note">Excluded neurons stay visible while you review. You can change your decision before applying the selection.</div><p style="margin-top:20px">Solid outline: kept<br>Dashed amber outline: excluded<br>White outline: selected</p><div class="footer-action">${btn(e.awaitingReview?'Apply & continue run':'Apply selection','apply-neurons',true)}</div></div></div></section>`;}
function results(e){return `<section class="panel"><h2>Results</h2><p>Each result should identify the settings and neuron selection that produced it.</p>${e.status==='Complete'?`${file('Analysis summary','Illustrative result from the latest demo run','Available')}${file('Neuron activity','Illustrative traces · preview only','Available')}${trace(4)}<div class="note">These are example result entries. No scientific output files are generated by this prototype.</div>`:`<div class="empty">${e.run?'Your demo analysis is running.':'Run the experiment to see the result layout.'}</div>${btn('Review and run','run',true,'play')}`}</section>`;}
function history(e){return `<div class="grid"><section class="panel"><div class="panel-head"><div><h2>Experiment history</h2><p>Your settings and decisions, saved as versions.</p></div>${btn('Save a version','save-version',true,'plus')}</div><div class="timeline">${e.history.map((v,i)=>`<article class="version"><small>${v.when}${i===0?' · Latest saved version':''}</small><h3>${esc(v.name)}</h3><p>Settings, crop and neuron selection</p><div class="row">${btn('See what changed',`compare:${i}`)}${btn('Restore this version',`restore:${i}`)}</div>${state.compare===i?diffView(v.snapshot,snapshot(e)):''}</article>`).join('')}</div></section><aside><section class="panel"><h3>A safe way to go back</h3><p>Restoring returns your tracked settings and decisions to a saved version. Your current work is saved first.</p><div class="note">History tracks analysis settings and references to results. It does not back up raw recordings or recreate missing result files.</div></section></aside></div>`;}
function diffView(a,b){const rows=[['Title',a.name,b.name],['Subject',a.subject,b.subject],['Notes',a.notes,b.notes],['Crop',a.crop.join(', '),b.crop.join(', ')],['Excluded neurons',a.excluded.join(', ')||'None',b.excluded.join(', ')||'None'],...Object.keys(a.settings).map(k=>[({event:'Event threshold',low:'Lower frequency',high:'Upper frequency',motion:'Motion correction'})[k],a.settings[k],b.settings[k]])].filter(([,a,b])=>a!==b);return `<div class="change"><strong>Saved version → current working settings</strong><br>${rows.length?rows.map(([k,a,b])=>`${k}: <del>${esc(a)}</del> → <ins>${esc(b)}</ins>`).join('<br>'):'No settings differences.'}</div>`;}
function dialog(e){if(!state.dialog)return '';if(state.dialog==='save-version')return `<form id="version-form" class="dialog"><h3>Save a version</h3><label class="field">What changed?<input required name="message" placeholder="e.g. Refined crop and reviewed neurons"></label><div class="row"><button class="primary">Save version</button>${btn('Cancel','close-dialog')}</div></form>`;if(state.dialog.startsWith('restore:')){const i=+state.dialog.split(':')[1];return `<div class="dialog"><h3>Restore “${esc(e.history[i].name)}”?</h3><p>We’ll save your current settings first, then restore this version. Results will need a new run if the settings change.</p>${diffView(e.history[i].snapshot,snapshot(e))}<div class="row">${btn('Save current work and restore',`confirm-restore:${i}`,true)}${btn('Cancel','close-dialog')}</div></div>`;}if(state.dialog==='run')return `<div class="dialog"><h3>${e.run?'Demo analysis in progress':'Review before running'}</h3>${e.run?`<p>Simulated progress. No analysis process is running.</p><div class="progress"><div style="width:${e.progress}%"></div></div><p>${e.progress}% · ${e.progress<50?'Preparing recording':e.progress<80?'Processing signals':'Preparing results'}</p><div class="row">${btn('Stop demo run','stop-run')}${btn('Keep browsing','close-dialog')}</div>`:`<p>Run ${e.type.toLowerCase()} analysis using the current settings. Save a version of these settings with the run.</p>${diffView(e.history[0].snapshot,snapshot(e))}<div class="summary-values"><span>Experiment ${e.id}</span><span>Crop: ${e.crop.join(', ')}</span><span>${12-e.excluded.length} neurons kept</span><span>Event threshold: ${e.settings.event}</span></div><div class="note">MVP behavior to validate: a changed crop produces new neuron candidates. Pause for review before computing final results.</div><div class="row">${e.status==='Check data'?'<span class="badge amber">Resolve missing data before running</span>':btn('Start demo run','start-run',true,'play')}${btn('Cancel','close-dialog')}</div>`}</div>`;return '';}
function addExperimentForm(project){return `<form id="experiment-form" class="dialog experiment-form"><h3>Add an experiment</h3><p>Adding to <strong>${esc(project.name)}</strong>.</p><p>Demo form. The finished flow will choose recording folders and validate the data.</p><div class="form-grid" style="margin-top:15px"><label class="field">Title<input name="name" required placeholder="Baseline · session 06"></label><label class="field">Subject<input name="subject" required placeholder="Rat 03"></label><label class="field">Recording type<select name="type"><option>Miniscope</option><option>Electrophysiology</option><option>Multimodal</option></select></label></div><div class="row" style="margin-top:15px"><button class="primary">Add demo experiment</button>${btn('Cancel','close-dialog')}</div></form>`;}
function switcher(){if(!['127.0.0.1','localhost',''].includes(location.hostname))return '';return `<div class="switcher" aria-label="Design variants">${btn('←','previous')}<span><small>DETAIL LAYOUT · OPEN AN EXPERIMENT TO COMPARE</small>${state.variant} — ${names[state.variant]}</span>${btn('→','next')}</div>`;}
let noticeTimer;
function notice(s){$('#notice').textContent=s;$('#notice').className='show';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').className='',4500);}
function changeVariant(dir){const variants=['A','B','C'];state.variant=variants[(variants.indexOf(state.variant)+dir+3)%3];const u=new URL(location);u.searchParams.set('variant',state.variant);window.history.replaceState(null,'',u);render();}
function saved(e,name){e.history.unshift({name,when:'Just now',snapshot:snapshot(e)});e.dirty=false;}
function dirty(e){e.dirty=true;if(e.status==='Complete')e.status='Ready to run';}
function action(a){const e=current();if(a==='home'){state.view='home';state.dialog=null;}else if(a.startsWith('folder:')){const p=projects.find(p=>p.id===+a.split(':')[1]);p.open=!p.open;}else if(a.startsWith('open:')){state.experiment=+a.split(':')[1];state.view='detail';state.tab='overview';state.dialog=null;state.compare=null;window.scrollTo(0,0);}else if(a.startsWith('tab:')){state.tab=a.split(':')[1];state.dialog=null;state.compare=null;}else if(a==='attention')state.attention=!state.attention;else if(a==='previous'||a==='next'){changeVariant(a==='next'?1:-1);return;}else if(a==='run'&&e.awaitingReview){state.tab='neurons';state.dialog=null;}else if(a==='add-project'||a.startsWith('add-experiment:')||a==='save-version'||a==='run'||a.startsWith('restore:')){state.dialog=a;}else if(a==='close-dialog')state.dialog=null;else if(a.startsWith('cell:'))e.selected=+a.split(':')[1];else if(a==='toggle-neuron'){e.excluded=e.excluded.includes(e.selected)?e.excluded.filter(n=>n!==e.selected):[...e.excluded,e.selected].sort((a,b)=>a-b);dirty(e);}else if(a==='apply-neurons'){dirty(e);if(e.awaitingReview){e.awaitingReview=false;saved(e,'Neuron selection for current run');e.run=Date.now();e.status='Running';state.dialog='run';tick(e,e.run);}else{e.status='Ready to run';}notice('Neuron selection applied to the demo experiment.');}else if(a==='reset-crop'){e.crop=[0,0,640,480];dirty(e);}else if(a.startsWith('compare:'))state.compare=state.compare===+a.split(':')[1]?null:+a.split(':')[1];else if(a.startsWith('confirm-restore:')){const v=structuredClone(e.history[+a.split(':')[1]]);saved(e,'Automatically saved before restore');Object.assign(e,structuredClone(v.snapshot));saved(e,`Restored: ${v.name}`);e.status='Ready to run';state.dialog=null;state.compare=null;notice('Demo version restored. Previous work is preserved in History.');}else if(a==='start-run'){saved(e,'Settings for analysis run');e.run=Date.now();e.progress=0;e.awaitingReview=false;e.status='Running';tick(e,e.run);}else if(a==='stop-run'){e.run=0;e.status='Ready to run';state.dialog=null;notice('Demo run stopped.');}render();}
function tick(e,token){setTimeout(()=>{if(e.run!==token)return;e.progress+=20;if(e.progress===60&&e.type!=='Electrophysiology'){e.run=0;e.awaitingReview=true;e.status='Review neurons';if(current()===e){state.dialog=null;state.tab='neurons';}notice('Demo run paused: review neuron candidates to continue.');}if(e.progress>=100){e.run=0;e.status='Complete';saved(e,'Analysis complete (demo)');if(current()===e)state.dialog=null;notice(`${e.name}: demo run complete.`);}if(state.view==='home'||current()===e)render();if(e.run)tick(e,token);},900);}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));$('#search')?.addEventListener('input',ev=>{const pos=ev.target.selectionStart;state.search=ev.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);});$('#project-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target);projects.push({id:Math.max(...projects.map(p=>p.id))+1,name:f.get('name'),description:'New project · sample folder',open:true});state.dialog=null;state.search='';state.attention=false;render();});$('#experiment-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),e=structuredClone(experiments[0]);e.id=Math.max(...experiments.map(e=>e.id))+1;e.project=+state.dialog.split(':')[1];e.name=f.get('name');e.subject=f.get('subject');e.type=f.get('type');e.status='Ready to run';e.run=0;e.history=[];saved(e,'Recording added');experiments.push(e);projects.find(p=>p.id===e.project).open=true;state.dialog=null;state.attention=false;render();});$('#settings-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),e=current();if(+f.get('low')>=+f.get('high')){notice('Lower frequency must be below upper frequency.');return;}e.name=f.get('name');e.subject=f.get('subject');e.notes=f.get('notes');e.settings={event:f.has('event')?+f.get('event'):e.settings.event,low:+f.get('low'),high:+f.get('high'),motion:f.get('motion')||e.settings.motion};dirty(e);render();notice('Settings applied in this preview. Save a version to add them to History.');});$('#version-form')?.addEventListener('submit',ev=>{ev.preventDefault();saved(current(),new FormData(ev.target).get('message'));state.dialog=null;render();notice('Version saved in demo history.');});$('#crop-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),c=[0,1,2,3].map(i=>+f.get(`c${i}`));if(c[0]>=c[2]||c[1]>=c[3]){notice('Right must be greater than left; bottom must be greater than top.');return;}current().crop=c;dirty(current());render();notice('Crop applied to the demo experiment.');});bindCrop();}
function bindCrop(){const svg=$('#crop-svg');if(!svg)return;let start=null;const point=ev=>{const r=svg.getBoundingClientRect();return [Math.max(0,Math.min(640,Math.round((ev.clientX-r.left)/r.width*640))),Math.max(0,Math.min(480,Math.round((ev.clientY-r.top)/r.height*480)))];};svg.addEventListener('pointerdown',ev=>{start=point(ev);svg.setPointerCapture(ev.pointerId);});svg.addEventListener('pointermove',ev=>{if(!start)return;const p=point(ev),c=[Math.min(start[0],p[0]),Math.min(start[1],p[1]),Math.max(start[0],p[0]),Math.max(start[1],p[1])];$('#crop-rect').setAttribute('x',c[0]);$('#crop-rect').setAttribute('y',c[1]);$('#crop-rect').setAttribute('width',c[2]-c[0]);$('#crop-rect').setAttribute('height',c[3]-c[1]);$('#crop-mask').setAttribute('d',mask(c));document.querySelectorAll('[data-crop]').forEach(el=>el.value=c[+el.dataset.crop]);});svg.addEventListener('pointerup',()=>start=null);svg.addEventListener('pointercancel',()=>start=null);}
document.addEventListener('keydown',ev=>{if(ev.target.closest('input,textarea,select,[contenteditable],#crop-svg')||ev.altKey||ev.metaKey||ev.ctrlKey)return;if(ev.key==='ArrowLeft'||ev.key==='ArrowRight'){ev.preventDefault();changeVariant(ev.key==='ArrowRight'?1:-1);}});
render();
